        constructor(inner: { 
        /**
         * The error encountered during execution.
         */error: ExecutionError, 
        /**
         * The command, if any, during which the error occurred.
         */command: /*u64*/bigint | undefined }) {
            super("ExecutionStatus", "Failure");
            this.inner = globalThis.Object.freeze(inner);
        }

        static new(inner: { 
        /**
         * The error encountered during execution.
         */error: ExecutionError, 
        /**
         * The command, if any, during which the error occurred.
         */command: /*u64*/bigint | undefined }): Failure_ {
            return new Failure_(inner);
        }

        static instanceOf(obj: any): obj is Failure_ {
            return obj.tag === ExecutionStatus_Tags.Failure;
        }

        

