/**
 * State of an object prior to execution
 *
 * If an object exists (at root-level) in the store prior to this transaction,
 * it should be Data, otherwise it's Missing, e.g. wrapped objects should be
 * Missing.
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 * object-in = object-in-missing / object-in-data
 *
 * object-in-missing = %x00
 * object-in-data    = %x01 u64 digest owner
 * ```
 */

export type ObjectIn = InstanceType<
    typeof ObjectIn[keyof Omit<typeof ObjectIn, 'instanceOf'>]
>;

// FfiConverter for enum ObjectIn
const FfiConverterTypeObjectIn = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = ObjectIn;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return new ObjectIn.Missing();
                case 2: return new ObjectIn.Data({version: FfiConverterUInt64.read(from), digest: FfiConverterTypeDigest.read(from), owner: FfiConverterTypeOwner.read(from) });
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value.tag) {
                case ObjectIn_Tags.Missing: {
                    ordinalConverter.write(1, into);
                    return;
                }
                case ObjectIn_Tags.Data: {
                    ordinalConverter.write(2, into);
                    const inner = value.inner;
                    FfiConverterUInt64.write(inner.version, into);
                    FfiConverterTypeDigest.write(inner.digest, into);
                    FfiConverterTypeOwner.write(inner.owner, into);
                    return;
                }
                default:
                    // Throwing from here means that ObjectIn_Tags hasn't matched an ordinal.
                    throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        allocationSize(value: TypeName): number {
            switch (value.tag) {
                case ObjectIn_Tags.Missing: {
                    return ordinalConverter.allocationSize(1);
                }
                case ObjectIn_Tags.Data: {
                    const inner = value.inner;
                    let size = ordinalConverter.allocationSize(2);
                    size += FfiConverterUInt64.allocationSize(inner.version);
                    size += FfiConverterTypeDigest.allocationSize(inner.digest);
                    size += FfiConverterTypeOwner.allocationSize(inner.owner);
                    return size;
                }
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
    }
    return new FFIConverter();
})();



